contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 valueBefore = c.value();
        uint256 remainingBefore = c.totalRemaining();
        uint256 senderBalanceBefore = c.balanceOf(address(this));

        bool reverted;
        try c.getTokens() { reverted = false; } catch { reverted = true; }

        uint256 senderBalanceAfter = c.balanceOf(address(this));
        uint256 remainingAfter = c.totalRemaining();

        uint256 expectedToGive = valueBefore <= remainingBefore ? valueBefore : remainingBefore;

        assert(!reverted ? (senderBalanceAfter == senderBalanceBefore + expectedToGive && remainingAfter == remainingBefore - expectedToGive) : (senderBalanceAfter == senderBalanceBefore && remainingAfter == remainingBefore));
    }

    receive() external payable {}
}

