contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address recipient) public {
        require(amount > 0);
        require(recipient != address(0));
        require(recipient != address(this));

        uint256 senderBal = c.balanceOf(address(this));
        require(senderBal >= amount);

        uint256 beforeRecipient = c.balanceOf(recipient);
        bool ok = c.approve(address(this), amount);
        require(ok);

        uint256 beforeAllowance = c.allowance(address(this), address(this));
        require(beforeAllowance == amount);

        bool reverted;
        bool success;
        try c.transferFrom(address(this), recipient, amount) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecipient = c.balanceOf(recipient);
        uint256 afterAllowance = c.allowance(address(this), address(this));

        if (!reverted) {
            assert(success && afterRecipient == beforeRecipient + amount && afterAllowance == beforeAllowance - amount);
        } else {
            assert(afterRecipient == beforeRecipient && afterAllowance == beforeAllowance);
        }
    }
}

